    if cap <= 0:
        return [[i] for i in range(n)]

    total = sum(items)

    # Lower bound: total capacity, plus simple cardinality bounds for large items.
    lb = (total + cap - 1) // cap
    lb = max(lb, sum(1 for s in items if 2 * s > cap))
    for k in range(3, 8):
        cnt = sum(1 for s in items if s * k > cap)
        lb = max(lb, (cnt + (k - 2)) // (k - 1))
    if n > 0 and lb < 1:
        lb = 1

    def make_bins(order, strategy):
        bins = []  # [load, [indices]]
        for i in order:
            s = items[i]
            best_idx = -1
            if strategy == "best":
                best_rem = cap + 1
                for b, (load, _) in enumerate(bins):
                    rem = cap - load
                    if rem >= s and rem < best_rem:
                        best_rem = rem
                        best_idx = b
                        if rem == s:
                            break
            elif strategy == "first":
                for b, (load, _) in enumerate(bins):
                    if load + s <= cap:
                        best_idx = b
                        break
            else:  # worst-fit
                best_rem = -1
                for b, (load, _) in enumerate(bins):
                    rem = cap - load
                    if rem >= s and rem > best_rem:
                        best_rem = rem
                        best_idx = b
            if best_idx == -1:
                bins.append([s, [i]])
            else:
                bins[best_idx][0] += s
                bins[best_idx][1].append(i)
        return bins

    # Try a few constructive variants; limit work for very large instances.
    if n > 2000:
        orders = [sorted(range(n), key=lambda i: (-items[i], i))]
        strategies = ["best"]
    else:
        orders = [
            sorted(range(n), key=lambda i: (-items[i], i)),
            sorted(range(n), key=lambda i: (items[i], i)),
            list(range(n)),
        ]
        strategies = ["best", "first"]

    best_bins = None
    best_key = None
    for order in orders:
        for strat in strategies:
            B = make_bins(order, strat)
            key = (len(B), sum((cap - b[0]) ** 2 for b in B))
            if best_bins is None or key < best_key:
                best_bins = B
                best_key = key

    if len(best_bins) <= lb:
        return [b[1] for b in best_bins]

