    deadline = time.monotonic() + 0.75

    improved = True
    while improved and len(bins) > lb and time.monotonic() < deadline:
        improved = False
        bin_order = sorted(
            range(len(bins)), key=lambda b: (bins[b][0], len(bins[b][1]))
        )

        for bidx in bin_order:
            if time.monotonic() >= deadline:
                break

            load, blist = bins[bidx]
            if not blist:
                bins.pop(bidx)
                improved = True
                break

            other_indices = [j for j in range(len(bins)) if j != bidx]
            total_rem = sum(cap - bins[j][0] for j in other_indices)
