                continue

            to_place = sorted(blist, key=lambda i: -items[i])
            sizes = [items[i] for i in to_place]
            m = len(sizes)
            if m == 0:
                bins.pop(bidx)
                improved = True
                break

            pairs = sorted(
                [(cap - bins[j][0], j) for j in other_indices],
                key=lambda x: -x[0],
            )
            caps = [p[0] for p in pairs]
            orig_ids = [p[1] for p in pairs]

            assignment = [-1] * m
            suffix_sum = [0] * (m + 1)
            for i in range(m - 1, -1, -1):
                suffix_sum[i] = suffix_sum[i + 1] + sizes[i]

            failed = set()
            nodes = 0
            node_limit = 20000
            timed_out = False
            total_cap = sum(caps)

            def dfs(pos, cap_left):
                nonlocal nodes, timed_out
                if pos == m:
                    return True
                if timed_out:
                    return False
                if nodes >= node_limit:
                    timed_out = True
                    return False
                if time.monotonic() >= deadline:
                    timed_out = True
                    return False
                if suffix_sum[pos] > cap_left:
                    return False

                nodes += 1

                key = None
                if len(caps) <= 20:
                    key = (pos, tuple(sorted(caps, reverse=True)))
                    if key in failed:
                        return False

                s = sizes[pos]
                tried = set()
                cand = []
                for idx, c in enumerate(caps):
                    if c >= s and c not in tried:
                        cand.append((c, idx))
                        tried.add(c)

                cand.sort(key=lambda x: x[0])  # best-fit: tighter bins first

                for c, idx in cand:
                    caps[idx] -= s
                    assignment[pos] = idx
                    if dfs(pos + 1, cap_left - s):
                        return True
                    caps[idx] += s
                    assignment[pos] = -1
                    if timed_out:
                        return False

                if key is not None:
                    failed.add(key)
                return False

            if dfs(0, total_cap):
                for pos, idx in enumerate(assignment):
                    orig_bin = orig_ids[idx]
                    item = to_place[pos]
                    bins[orig_bin][0] += items[item]
                    bins[orig_bin][1].append(item)
                bins.pop(bidx)
                improved = True
                break

    return [b[1] for b in bins if b[1]]

