def pack(payload):
    items = payload["items"]
    cap = payload["capacity"]
    n = len(items)

    if n == 0:
        return []
    if cap <= 0:
        return [[i] for i in range(n)]

    # Trivial optimal cases
    if len(set(items)) == 1:
        s = items[0]
        per_bin = max(1, cap // s)
        bins = []
        cur = []
        for i in range(n):
            cur.append(i)
            if len(cur) == per_bin:
                bins.append(cur)
                cur = []
        if cur:
            bins.append(cur)
        return bins

    if 2 * min(items) > cap:
        return [[i] for i in range(n)]

    start_time = time.monotonic()
    deadline = start_time + 0.85
    sys.setrecursionlimit(10000)

    total = sum(items)
    lb = (total + cap - 1) // cap
    for k in range(2, 10):
        cnt = sum(1 for s in items if s * k > cap)
        if cnt > 0:
            lb = max(lb, (cnt + (k - 2)) // (k - 1))
    if lb < 1:
        lb = 1

    def solve_exact(items, cap, deadline):
        freq = Counter(items)
        sizes = sorted(freq.keys(), reverse=True)
        m = len(sizes)
        if m == 0:
            return []
        counts = tuple(freq[s] for s in sizes)

        patterns = []
        def gen(idx, current, total):
            if idx == m:
                patterns.append((tuple(current), total))
                return
            maxc = cap // sizes[idx]
            for c in range(maxc + 1):
                if total + c * sizes[idx] <= cap:
                    current.append(c)
                    gen(idx + 1, current, total + c * sizes[idx])
                    current.pop()
        gen(0, [], 0)
        patterns.sort(key=lambda x: -x[1])

        pby = [[] for _ in range(m)]
        for p, total in patterns:
            for i in range(m):
                if p[i] > 0:
                    pby[i].append((p, total))

        memo = {}
        INF = 10**9
        nodes = 0

        def solve(state):
            nonlocal nodes
            if nodes > 200000 or time.monotonic() > deadline:
                raise TimeoutError
            if sum(state) == 0:
                return 0
            if state in memo:
                return memo[state]
            nodes += 1
            total = sum(state[i] * sizes[i] for i in range(m))
            lb_state = (total + cap - 1) // cap

            i = 0
            while i < m and state[i] == 0:
                i += 1

            best = INF
            for p, ptotal in pby[i]:
                ok = True
                for j in range(m):
                    if p[j] > state[j]:
                        ok = False
                        break
                if not ok:
                    continue

                maximal = True
                for j in range(m):
                    if p[j] < state[j] and ptotal + sizes[j] <= cap:
                        maximal = False
                        break
                if not maximal:
                    continue

                new_state = tuple(state[j] - p[j] for j in range(m))
                res = 1 + solve(new_state)
                if res < best:
                    best = res
                    if best <= lb_state:
                        break
            memo[state] = best
            return best

        try:
            min_bins = solve(counts)
        except TimeoutError:
            return None
        if min_bins >= INF:
            return None

        state = counts
        result_patterns = []
        while sum(state) > 0:
            i = 0
            while i < m and state[i] == 0:
                i += 1
            best = memo[state]
            found = False
            for p, ptotal in pby[i]:
                ok = True
                for j in range(m):
                    if p[j] > state[j]:
                        ok = False
                        break
                if not ok:
                    continue

                maximal = True
                for j in range(m):
                    if p[j] < state[j] and ptotal + sizes[j] <= cap:
                        maximal = False
                        break
                if not maximal:
                    continue

                new_state = tuple(state[j] - p[j] for j in range(m))
                if sum(new_state) == 0:
                    res = 1
                else:
                    res = 1 + memo.get(new_state, INF)
                if res == best:
                    result_patterns.append(p)
                    state = new_state
                    found = True
                    break
            if not found:
                return None

        indices_by_size = defaultdict(list)
        for idx, s in enumerate(items):
            indices_by_size[s].append(idx)

        bins = []
        for p in result_patterns:
            bin_indices = []
            for j, cnt in enumerate(p):
                if cnt > 0:
                    s = sizes[j]
                    for _ in range(cnt):
                        bin_indices.append(indices_by_size[s].pop())
            bins.append(bin_indices)
        return bins

    def local_search(bins, items, cap, lb, deadline):
        def try_repack_into_caps(item_indices, caps, items, deadline):
            sorted_items = sorted(item_indices, key=lambda i: -items[i])
            m = len(sorted_items)
            n_caps = len(caps)
            loads = [0] * n_caps
