            suffix = [0] * (m + 1)
            for i in range(m - 1, -1, -1):
                suffix[i] = suffix[i + 1] + items[sorted_items[i]]
            failed = set()

            def dfs(pos):
                if time.monotonic() > deadline:
                    raise TimeoutError
                if pos == m:
                    return True
                rem_cap = sum(caps[b] - loads[b] for b in range(n_caps))
                if suffix[pos] > rem_cap:
                    return False
                key = (pos, tuple(sorted([caps[b] - loads[b] for b in range(n_caps)], reverse=True)))
                if key in failed:
                    return False
                s = items[sorted_items[pos]]
                tried = set()
                order = sorted(range(n_caps), key=lambda b: caps[b] - loads[b])
                for b in order:
                    rem = caps[b] - loads[b]
                    if rem >= s and rem not in tried:
                        tried.add(rem)
                        loads[b] += s
                        assignment[b].append(sorted_items[pos])
                        if dfs(pos + 1):
                            return True
                        assignment[b].pop()
                        loads[b] -= s
                failed.add(key)
                return False

            try:
                if dfs(0):
                    return assignment
            except TimeoutError:
                return None
            return None

        def try_pack_items(item_indices, target_bins, cap, items, deadline):
            if target_bins == 0:
                return [] if not item_indices else None
            if sum(items[i] for i in item_indices) > target_bins * cap:
                return None
            sorted_items = sorted(item_indices, key=lambda i: -items[i])
            m = len(sorted_items)
            new_bins = [[] for _ in range(target_bins)]
            loads = [0] * target_bins
            failed = set()
            suffix = [0] * (m + 1)
            for i in range(m - 1, -1, -1):
                suffix[i] = suffix[i + 1] + items[sorted_items[i]]

            def dfs(pos):
                if time.monotonic() > deadline:
                    raise TimeoutError
                if pos == m:
                    return True
                if suffix[pos] > sum(cap - loads[b] for b in range(target_bins)):
                    return False
                key = (pos, tuple(sorted(loads, reverse=True)))
                if key in failed:
                    return False
                s = items[sorted_items[pos]]
                tried = set()
                order = sorted(range(target_bins), key=lambda b: -loads[b])
                for b in order:
                    if loads[b] + s <= cap and loads[b] not in tried:
                        tried.add(loads[b])
                        loads[b] += s
                        new_bins[b].append(sorted_items[pos])
                        if dfs(pos + 1):
                            return True
                        new_bins[b].pop()
                        loads[b] -= s
                failed.add(key)
                return False

            try:
                if dfs(0):
                    return new_bins
            except TimeoutError:
                return None
            return None

        while len(bins) > lb and time.monotonic() < deadline:
            improved = False

            # 1. Try to eliminate a single bin by redistributing its items.
            bin_order = sorted(range(len(bins)), key=lambda b: bins[b][0])
            for bidx in bin_order:
                if time.monotonic() >= deadline:
                    break
                load, blist = bins[bidx]
                if not blist:
                    bins.pop(bidx)
                    improved = True
                    break
                other_indices = [j for j in range(len(bins)) if j != bidx]
                caps = [cap - bins[j][0] for j in other_indices]
                if sum(caps) < load:
                    continue
                assignment = try_repack_into_caps(blist, caps, items, deadline)
                if assignment is not None:
                    for pos, j in enumerate(other_indices):
                        for item in assignment[pos]:
                            bins[j][0] += items[item]
                            bins[j][1].append(item)
                    bins.pop(bidx)
                    improved = True
                    break
            if improved:
                continue

            # 2. Try to repack any three bins into two bins.
            B = len(bins)
            if 3 <= B <= 45:
                triples = []
                for i in range(B):
                    for j in range(i + 1, B):
                        for k in range(j + 1, B):
                            total_load = bins[i][0] + bins[j][0] + bins[k][0]
                            if total_load <= 2 * cap:
                                triples.append((total_load, i, j, k))
                triples.sort(reverse=True)

                for total_load, i, j, k in triples:
                    if time.monotonic() >= deadline:
                        break
                    item_indices = bins[i][1] + bins[j][1] + bins[k][1]
                    new_bins_indices = try_pack_items(item_indices, 2, cap, items, deadline)
                    if new_bins_indices is not None:
                        for idx in sorted([i, j, k], reverse=True):
                            bins.pop(idx)
                        for new_bin in new_bins_indices:
                            if new_bin:
                                load_new = sum(items[x] for x in new_bin)
                                bins.append([load_new, new_bin])
                        improved = True
                        break
            if improved:
                continue

            if not improved:
                break

        return bins

    # Exact solver for instances with very few distinct item sizes.
    best_exact_bins = None
    distinct = set(items)
    if len(distinct) <= 5 and n <= 1000:
        exact_deadline = start_time + 0.4
        exact_bins = solve_exact(items, cap, exact_deadline)
        if exact_bins is not None:
            best_exact_bins = exact_bins
            if len(best_exact_bins) <= lb:
                return best_exact_bins

    # Constructive heuristics.
    def make_bins(order, strategy):
        bins = []
        for i in order:
            s = items[i]
            best_idx = -1
            if strategy == "best":
                best_rem = cap + 1
                for b, (load, _) in enumerate(bins):
                    rem = cap - load
