import time


def pack(payload):
    items = payload["items"]
    cap = payload["capacity"]
    n = len(items)

    if n == 0:
        return []
    if cap <= 0:
        return [[i] for i in range(n)]

    start = time.monotonic()
    deadline = start + 0.95

    total = sum(items)

    # Lower bounds
    lb = (total + cap - 1) // cap
    lb = max(lb, sum(1 for s in items if 2 * s > cap))
    for k in range(3, 12):
        cnt = sum(1 for s in items if s * k > cap)
        if cnt:
            lb = max(lb, (cnt + (k - 2)) // (k - 1))
    if lb < 1:
        lb = 1

    def make_bins(order, strategy):
        bins = []
        loads = []
        for i in order:
            s = items[i]
            best_idx = -1

            if strategy == "best":
                best_rem = cap + 1
                for b, load in enumerate(loads):
                    rem = cap - load
                    if rem >= s and rem < best_rem:
                        best_rem = rem
                        best_idx = b
                        if rem == s:
                            break
            elif strategy == "first":
                for b, load in enumerate(loads):
                    if load + s <= cap:
                        best_idx = b
                        break
            else:  # worst-fit
                best_rem = -1
                for b, load in enumerate(loads):
                    rem = cap - load
                    if rem >= s and rem > best_rem:
                        best_rem = rem
                        best_idx = b

            if best_idx == -1:
                bins.append([i])
                loads.append(s)
            else:
                bins[best_idx].append(i)
                loads[best_idx] += s
        return bins

    best_bins = None
    best_key = None

    def consider(b):
        nonlocal best_bins, best_key
        b = [bin for bin in b if bin]
        if not b and n > 0:
            return
        loads = [sum(items[i] for i in bin) for bin in b]
        key = (len(b), sum((cap - load) ** 2 for load in loads))
        if best_bins is None or key < best_key:
            best_bins = [bin[:] for bin in b]
            best_key = key

    # Basic constructive methods
    orders = [
        sorted(range(n), key=lambda i: (-items[i], i)),
        sorted(range(n), key=lambda i: (items[i], i)),
        list(range(n)),
    ]
    strategies = ["best", "first", "worst"]

    for order in orders:
        for strat in strategies:
            consider(make_bins(order, strat))
            if time.monotonic() > deadline:
                break
        if time.monotonic() > deadline:
            break

    # Bitset subset-sum for minimum-bin-slack (MBS)
    def subset_sum_max(rem):
        limit_mask = (1 << (cap + 1)) - 1
        mask = 1
        masks = [1]
        for idx in rem:
            s = items[idx]
            mask = (mask | (mask << s)) & limit_mask
            masks.append(mask)

        best = mask.bit_length() - 1
        chosen = []
        cur = best

        for j in range(len(rem) - 1, -1, -1):
            idx = rem[j]
            s = items[idx]
            if (masks[j] >> cur) & 1:
                continue
            chosen.append(idx)
            cur -= s
            if cur < 0:
                break
        return chosen

    def mbs_solution(order, mbs_deadline):
        rem = order[:]
        bins = []
        while rem:
            if time.monotonic() > mbs_deadline:
                bins.extend(make_bins(rem, "best"))
                break
            chosen = subset_sum_max(rem)
            if not chosen:
                chosen = [rem[0]]
            bins.append(chosen)
            chosen_set = set(chosen)
            rem = [i for i in rem if i not in chosen_set]
        return bins

    if cap <= 20000 and n > 0:
        mbs_orders = [
            sorted(range(n), key=lambda i: -items[i]),
            sorted(range(n), key=lambda i: items[i]),
            list(range(n)),
        ]
        for mbs_order in mbs_orders:
            if time.monotonic() > start + 0.5:
                break
            b = mbs_solution(mbs_order, min(deadline, start + 0.7))
            consider(b)

    if best_bins is None:
        best_bins = make_bins(list(range(n)), "best")

    if len(best_bins) <= lb:
        return [b for b in best_bins if b]

    # Exact/backtracking packer for selected items
    def pack_into(indices, max_bins, p_deadline, node_limit=50000):
        if not indices:
            return []
        if max_bins <= 0:
            return None

        total_sub = sum(items[i] for i in indices)
        if total_sub > max_bins * cap:
            return None

        # Quick BFD attempt
        order = sorted(indices, key=lambda i: -items[i])
        bins_g = []
        loads_g = []

        for i in order:
            s = items[i]
            best = -1
            best_rem = cap + 1
            for b, load in enumerate(loads_g):
                rem = cap - load
                if rem >= s and rem < best_rem:
                    best_rem = rem
                    best = b

            if best == -1:
                if len(bins_g) >= max_bins:
                    break
                bins_g.append([i])
                loads_g.append(s)
            else:
                bins_g[best].append(i)
                loads_g[best] += s

        if sum(len(b) for b in bins_g) == len(indices):
            return bins_g

        sizes = [(items[i], i) for i in indices]
        sizes.sort(key=lambda x: -x[0])
        n2 = len(sizes)

        loads = [0] * max_bins
        bin_items = [[] for _ in range(max_bins)]
        failed = set()
        nodes = 0

        def dfs(pos):
            nonlocal nodes
            if pos == n2:
                return True
            if nodes >= node_limit or time.monotonic() > p_deadline:
                return False

            key = (pos, tuple(sorted(loads, reverse=True)))
            if key in failed:
                return False

            nodes += 1
            s, idx = sizes[pos]

            cand = []
            for b in range(max_bins):
                if loads[b] + s <= cap:
                    cand.append((loads[b], b))
            cand.sort(key=lambda x: -x[0])

            tried = set()
            for load_val, b in cand:
