        # Repack the k emptiest bins into k-1 bins.
        repacked = False
        order = sorted(range(len(bins)), key=lambda b: sum(items[i] for i in bins[b]))
        max_k = min(12, len(bins))

        for k in range(2, max_k + 1):
            selected = order[:k]
            total_sel = sum(sum(items[i] for i in bins[b]) for b in selected)

            if total_sel > (k - 1) * cap:
                continue
            if (total_sel + cap - 1) // cap > k - 1:
                continue

            sub = []
            for b in selected:
                sub.extend(bins[b])

            res = pack_into(
                sub,
                k - 1,
                min(deadline, time.monotonic() + 0.04),
                node_limit=20000,
            )

            if res is not None:
                new_bins = []
                selected_set = set(selected)
                for b in range(len(bins)):
                    if b not in selected_set:
                        new_bins.append(bins[b])
                new_bins.extend(res)
                bins = new_bins
                repacked = True
                break

        if repacked:
            continue

        # Try target bin plus k-1 emptiest bins into k-1 bins.
        for target in order[:min(len(order), 6)]:
            if time.monotonic() > deadline:
                break

            others = [b for b in order if b != target]

            for k in range(2, min(10, len(bins)) + 1):
                selected = [target] + others[:k - 1]
                total_sel = sum(sum(items[i] for i in bins[b]) for b in selected)

                if total_sel > (k - 1) * cap:
                    continue
                if (total_sel + cap - 1) // cap > k - 1:
                    continue

                sub = []
                for b in selected:
                    sub.extend(bins[b])

                res = pack_into(
                    sub,
                    k - 1,
                    min(deadline, time.monotonic() + 0.04),
                    node_limit=20000,
                )

                if res is not None:
                    new_bins = []
                    selected_set = set(selected)
                    for b in range(len(bins)):
                        if b not in selected_set:
                            new_bins.append(bins[b])
                    new_bins.extend(res)
                    bins = new_bins
                    repacked = True
                    break

            if repacked:
                break

        if repacked:
            continue

        # Try any three bins into two bins.
        if 3 <= len(bins) <= 50:
            triples = []
            B = len(bins)
            for i in range(B):
                for j in range(i + 1, B):
                    for k in range(j + 1, B):
                        total_load = loads[i] + loads[j] + loads[k]
                        if total_load <= 2 * cap:
                            triples.append((total_load, i, j, k))
            triples.sort(reverse=True)

            for total_load, i, j, k in triples[:30]:
                if time.monotonic() > deadline:
                    break
                sub = bins[i] + bins[j] + bins[k]
                res = pack_into(
                    sub,
                    2,
                    min(deadline, time.monotonic() + 0.05),
                    node_limit=30000,
                )
                if res is not None:
                    for idx in sorted([i, j, k], reverse=True):
                        bins.pop(idx)
                    for nb in res:
                        if nb:
                            bins.append(nb)
                    repacked = True
                    break

            if repacked:
                continue

        break

    consider(bins)

    # Final exact improvement for small instances.
    if (
        time.monotonic() < deadline
        and best_bins is not None
        and len(best_bins) > lb
        and (n <= 45 or (len(best_bins) <= 25 and n <= 120))
    ):
        while time.monotonic() < deadline and len(best_bins) > lb:
            res = pack_into(
                list(range(n)),
                len(best_bins) - 1,
                min(deadline, time.monotonic() + 0.2),
                node_limit=500000,
            )
            if res is not None:
                consider(res)
            else:
                break

    if best_bins is None:
        best_bins = make_bins(list(range(n)), "best")

    return [b for b in best_bins if b]
